#!/bin/bash
# Set or toggle Ghostty's window padding on one axis — the knob that decides
# how wide (x) or tall (y) the text column is. Aliases: `ww` (x), `wh` (y).
#
#   padding.sh x       -> toggle between the x presets (400 <-> 600)
#   padding.sh y 80    -> any value you like, not just a preset
#
# Each axis writes one gitignored include of ghostty/config: width-active.conf
# for x, height-active.conf for y, so changing padding never dirties the
# tracked config. The payload is a single number, so a generated file beats
# the symlink-to-a-variant idiom the theme uses.
#
# Larger padding = smaller text column. Ghostty re-reads its config on
# cmd+shift+, and applies padding to new windows and tabs only.
set -u

usage() {
    printf 'usage: padding.sh x|y [POINTS]   (no POINTS toggles presets)\n' >&2
    exit 2
}

case "${1:-}" in
    x) PRESETS=(400 600); FILE=width-active.conf; alias_name=ww ;;
    y) PRESETS=(12 120); FILE=height-active.conf; alias_name=wh ;;
    *) usage ;;
esac
axis="$1"
shift

RC_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ACTIVE="$RC_DIR/ghostty/$FILE"
KEY="window-padding-$axis"

# Current value, read back from the file we write. Absent or unparseable counts
# as "unset", which the toggle treats as "go to the first preset".
cur=""
[ -f "$ACTIVE" ] && cur="$(sed -n \
    "s/^[[:space:]]*$KEY[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p" \
    "$ACTIVE" | head -1)"

if [ $# -gt 0 ]; then
    case "$1" in
        -h|--help) usage ;;
        # Any value is allowed, but it still has to be a number — a typo here
        # lands in a config file that ghostty refuses wholesale, taking the
        # theme include down with it.
        ''|*[!0-9]*)
            printf 'padding.sh: %s is not a number\n' "$1" >&2
            exit 1
            ;;
    esac
    next="$1"
else
    # Toggle: whichever preset is not the current value. Anything else — unset,
    # or an arbitrary value set earlier — lands on the first preset.
    if [ "$cur" = "${PRESETS[0]}" ]; then
        next="${PRESETS[1]}"
    else
        next="${PRESETS[0]}"
    fi
fi

mkdir -p "$(dirname "$ACTIVE")"
cat > "$ACTIVE" <<EOF
# GENERATED by padding.sh (alias \`$alias_name\`) — edits here are overwritten.
# Included by ghostty/config; gitignored so it never dirties the repo.
$KEY = $next
EOF

printf 'ghostty padding-%s: %s -> %s  (cmd+shift+, to reload)\n' \
    "$axis" "${cur:-unset}" "$next"
